style
/* === DESIGN TOKENS === */
:root {
--font-ui:    &apos;Figtree&apos;, system-ui, sans-serif;
--font-brand: &apos;Sora&apos;, system-ui, sans-serif;
--font-mono:  &apos;Fira Code&apos;, &apos;Cascadia Code&apos;, monospace;
--r-sm: 4px; --r-md: 6px; --r-pill: 20px;
}

/* === LIGHT THEME  CVS === */
:root, [data-theme=light] {
--bg:            #F2F2F7;
--bg-surface:    #E8E8F0;
--bg-elevated:   #FAFAFA;
--bg-inset:      #E0E0EA;
--border:        #C8C8D8;
--border-strong: #AAAABB;
--text-1: #0E0E18;
--text-2: #3A3A52;
--text-3: #70708A;
--text-4: #AAAABB;
--accent:       #CC0000;
--accent-h:     #A80000;
--accent-dim:   #FFF0F0;
--accent-bd:    #F8BBBB;
--tab-find-bg:  #CC0000; --tab-find-bd: #CC0000; --tab-find-fg: #FFFFFF;
--tab-exp-bg:   #145A32; --tab-exp-bd:  #145A32; --tab-exp-fg: #FFFFFF;
--input-bg:  #FAFAFA; --input-bd: #BBBBCC; --input-focus: #CC0000;
--th-bg: #E4E4EE; --th-fg: #CC0000;
--tr-hover: #FFF0F0; --tr-bd: #DDDDE8;
--chip-bg: #E4E4EE; --chip-bd: #BBBBC8; --chip-fg: #3A3A52;
--badge-bg: #EEF2FF; --badge-bd: #C7D2FE; --badge-fg: #3730A3;
--on-bg:   #DCFCE7; --on-bd:   #4ADE80; --on-fg:   #052E16;
--off-bg:  #EDEDF2; --off-bd:  #BBBBC8; --off-fg:  #3A3A52;
--susp-bg: #FEF3C7; --susp-bd: #F59E0B; --susp-fg: #451A03;
--tmpl-bg: #EEF2FF; --tmpl-bd: #C7D2FE; --tmpl-fg: #312E81;
--maint-bg:#FEF3C7; --maint-bd:#F59E0B; --maint-fg:#451A03;
--util-track: #D4D4E0;
--util-low: #166534; --util-mid: #92400E; --util-high: #991B1B;
--link: #CC0000; --link-h: #A80000;
--detail-bg: #FAFAFA; --detail-bd: #C8C8D8;
--detail-shadow: -12px 0 40px rgba(0,0,0,0.13);
--detail-label: #70708A; --detail-section: #E8E8F0;
--tree-root-bg: #EFEFF4; --tree-node-bg: #FAFAFA;
--tree-l2-bg: #E8E8F0; --tree-l3-bg: #E0E0EA;
--tree-leaf-bd: #DDDDE8; --tree-flat-bg: #E8E8F0;
--group-bg: #FAFAFA; --group-hdr: #E8E8F0;
--overlay-bg: rgba(0,0,0,0.40);
--c-good: #166534; --c-warn: #D97706; --c-bad: #CC0000;
--c-hi: #0E0E18; --c-mid: #3A3A52; --c-lo: #52526A;
--header-bg: #FAFAFA; --searchbar-bg: #F2F2F7; --hint-bg: #E8E8F0;
color-scheme: light;
}

/* === DARK THEME  AETNA === */
[data-theme=dark] {
--bg:            #0C0912;
--bg-surface:    #150E20;
--bg-elevated:   #1B1230;
--bg-inset:      #0F0C1A;
--border:        #291740;
--border-strong: #3C2458;
--text-1: #EDE8F6;
--text-2: #C8BCDC;
--text-3: #9080A8;
--text-4: #5A4468;
--accent:       #9333EA;
--accent-h:     #A855F7;
--accent-dim:   #170B26;
--accent-bd:    #481870;
--tab-find-bg:  #7B2D8B; --tab-find-bd: #9B3DAB; --tab-find-fg: #F0EBF8;
--tab-exp-bg:   #064E3B; --tab-exp-bd:  #065F46; --tab-exp-fg: #6EE7B7;
--input-bg:  #0C0912; --input-bd: #3C2458; --input-focus: #9333EA;
--th-bg: #150E20; --th-fg: #C084FC;
--tr-hover: #160A28; --tr-bd: #1B1230;
--chip-bg: #0C0912; --chip-bd: #291740; --chip-fg: #68547C;
--badge-bg: #0D0922; --badge-bd: #3B2D6E; --badge-fg: #A78BFA;
--on-bg:   #052E16; --on-bd:   #166534; --on-fg:   #4ADE80;
--off-bg:  #1C1917; --off-bd:  #44403C; --off-fg:  #78716C;
--susp-bg: #422006; --susp-bd: #92400E; --susp-fg: #FBBF24;
--tmpl-bg: #1E1B4B; --tmpl-bd: #4338CA; --tmpl-fg: #A5B4FC;
--maint-bg:#422006; --maint-bd:#D97706; --maint-fg:#FBBF24;
--util-track: #1B1230;
--util-low: #22C55E; --util-mid: #F59E0B; --util-high: #EF4444;
--link: #C084FC; --link-h: #D8B4FE;
--detail-bg: #150E20; --detail-bd: #291740;
--detail-shadow: -16px 0 48px rgba(0,0,0,0.60);
--detail-label: #9080A8; --detail-section: #1B1230;
--tree-root-bg: #150E20; --tree-node-bg: #110A1C;
--tree-l2-bg: #0C0912; --tree-l3-bg: #090712;
--tree-leaf-bd: #1B1230; --tree-flat-bg: #0C0912;
--group-bg: #150E20; --group-hdr: #1B1230;
--overlay-bg: rgba(0,0,0,0.65);
--c-good: #4ADE80; --c-warn: #FBBF24; --c-bad: #F87171;
--c-hi: #F1F5F9; --c-mid: #94A3B8; --c-lo: #64748B;
--header-bg: #0F0B1C; --searchbar-bg: #0F0B1C; --hint-bg: #150E20;
color-scheme: dark;
}

/* === RESET === */
* { box-sizing: border-box; margin: 0; padding: 0; }

body {
font-family: var(--font-ui);
background: var(--bg);
color: var(--text-1);
min-height: 100vh;
-webkit-font-smoothing: antialiased;
}

/* === HEADER === */
header {
background: var(--header-bg);
border-bottom: 1px solid var(--border);
padding: 12px 28px;
display: flex;
align-items: center;
gap: 14px;
}
header h1 {
font-family: var(--font-brand);
font-size: 1rem;
font-weight: 600;
color: var(--accent);
letter-spacing: 0.01em;
}
#stats { margin-left: auto; font-size: 0.72rem; color: var(--text-3); font-family: var(--font-mono); }

#theme-toggle {
background: none;
border: 1px solid var(--border);
color: var(--text-3);
padding: 5px 11px;
border-radius: var(--r-sm);
cursor: pointer;
font-size: 0.74rem;
font-family: var(--font-ui);
transition: all 0.15s;
white-space: nowrap;
flex-shrink: 0;
}
#theme-toggle:hover { border-color: var(--accent); color: var(--accent); }

/* === SEARCH BAR === */
.search-bar {
background: var(--searchbar-bg);
border-bottom: 1px solid var(--border);
padding: 11px 28px;
display: flex;
gap: 10px;
align-items: center;
flex-wrap: wrap;
}
.tab-groups { display: flex; align-items: center; gap: 4px; }
.tab-divider { width: 1px; height: 22px; background: var(--border); margin: 0 8px; }
.tab-group-label {
font-size: 0.63rem; color: var(--text-3); text-transform: uppercase;
letter-spacing: 0.09em; padding-right: 4px; white-space: nowrap; font-weight: 600;
font-family: var(--font-brand);
}
.field-tabs { display: flex; gap: 3px; }
.field-tabs button {
background: var(--bg-inset); border: 1px solid var(--border); color: var(--text-2);
padding: 5px 13px; border-radius: var(--r-sm); cursor: pointer; font-size: 0.76rem;
font-family: var(--font-ui); font-weight: 500; transition: all 0.15s;
}
.field-tabs button.active { background: var(--tab-find-bg); border-color: var(--tab-find-bd); color: var(--tab-find-fg); }
.field-tabs.explore button.active { background: var(--tab-exp-bg); border-color: var(--tab-exp-bd); color: var(--tab-exp-fg); }
.field-tabs button:hover:not(.active) { border-color: var(--border-strong); color: var(--text-1); }

#group-by-wrap { display: none; gap: 6px; align-items: center; }
#group-by-wrap  span { font-size: 0.7rem; color: var(--text-3); white-space: nowrap; }
.search-row { display: flex; gap: 10px; align-items: center; flex: 1; min-width: 0; }

#search-input {
flex: 1; min-width: 260px; background: var(--input-bg); border: 1px solid var(--input-bd);
color: var(--text-1); padding: 8px 14px; border-radius: var(--r-sm); font-size: 0.9rem;
font-family: var(--font-ui); outline: none; transition: border-color 0.15s;
}
#search-input:focus { border-color: var(--input-focus); }
#search-input::placeholder { color: var(--text-3); }

#search-btn {
background: var(--accent); border: none; color: #fff; padding: 8px 22px;
border-radius: var(--r-sm); cursor: pointer; font-size: 0.86rem;
font-family: var(--font-ui); font-weight: 600; transition: background 0.15s; white-space: nowrap;
}
#search-btn:hover { background: var(--accent-h); }

#about-btn {
background: none; border: 1px solid var(--border); color: var(--text-3);
padding: 7px 14px; border-radius: var(--r-sm); cursor: pointer; font-size: 0.74rem;
font-family: var(--font-ui); transition: all 0.15s;
}
#about-btn:hover { border-color: var(--border-strong); color: var(--text-2); }

#export-btn {
background: none; border: 1px solid var(--border); color: var(--text-3);
padding: 7px 14px; border-radius: var(--r-sm); cursor: pointer; font-size: 0.74rem;
font-family: var(--font-ui); transition: all 0.15s;
}
#export-btn:not([disabled]):hover { border-color: var(--util-low); color: var(--util-low); }
#export-btn[disabled] { opacity: 0.3; cursor: default; }

#search-hint {
font-size: 0.71rem; color: var(--text-3); padding: 5px 28px 7px;
background: var(--hint-bg); border-bottom: 1px solid var(--border);
}
#search-hint em { color: var(--text-2); font-style: normal; }

/* === MAIN === */
.main { padding: 22px 28px; }
#status { font-size: 0.79rem; color: var(--text-3); margin-bottom: 10px; min-height: 1.2em; }

/* === CHIPS === */
#power-chips-wrap { display: none; margin-bottom: 14px; }
.power-chips { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; }
.chip {
background: var(--chip-bg); border: 1px solid var(--chip-bd); color: var(--chip-fg);
padding: 3px 12px; border-radius: var(--r-pill); cursor: pointer; font-size: 0.7rem;
font-family: var(--font-ui); font-weight: 500; transition: all 0.15s; white-space: nowrap;
}
.chip:hover:not(.active) { border-color: var(--border-strong); color: var(--text-2); }
.chip.active { background: var(--bg-elevated); border-color: var(--border-strong); color: var(--text-1); }
.chip.active.on   { background: var(--on-bg);   border-color: var(--on-bd);   color: var(--on-fg); }
.chip.active.off  { background: var(--off-bg);  border-color: var(--off-bd);  color: var(--off-fg); }
.chip.active.susp { background: var(--susp-bg); border-color: var(--susp-bd); color: var(--susp-fg); }
.chip.active.tmpl { background: var(--tmpl-bg); border-color: var(--tmpl-bd); color: var(--tmpl-fg); }
.chip.active.oos  { background: #450a0a; border-color: #991b1b; color: #f87171; }
.chip.active.maint{ background: var(--maint-bg); border-color: var(--maint-bd); color: var(--maint-fg); }
#host-chips-wrap { display: none; margin-bottom: 14px; }

/* === RESULT SUMMARY STRIP === */
.result-summary { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; padding: 6px 0 12px; }
.summary-pill {
display: inline-flex; align-items: center; gap: 4px;
background: var(--bg-surface); border: 1px solid var(--border);
border-radius: var(--r-pill); padding: 3px 11px 3px 9px;
font-size: 0.71rem; color: var(--text-2); cursor: pointer;
transition: border-color 0.12s, background 0.12s; user-select: none;
}
.summary-pill:hover { border-color: var(--border-strong); background: var(--bg-inset); }
.summary-pill .sp-n { font-weight: 700; font-family: var(--font-mono); color: var(--text-1); margin-right: 1px; }
.summary-pill.sp-good { border-color: var(--on-bd); background: var(--on-bg); color: var(--on-fg); }
.summary-pill.sp-good .sp-n { color: var(--on-fg); }
.summary-pill.sp-warn { border-color: var(--susp-bd); background: var(--susp-bg); color: var(--susp-fg); }
.summary-pill.sp-warn .sp-n { color: var(--susp-fg); }
.summary-pill.sp-bad  { border-color: var(--c-bad); background: var(--accent-dim); color: var(--c-bad); }
.summary-pill.sp-bad  .sp-n { color: var(--c-bad); }
.summary-pill.sp-dim  { cursor: default; }

/* === SCOPE CHIP === */
#scope-chip { margin-bottom: 6px; }
.scope-chip {
display: inline-flex; align-items: center; gap: 6px;
background: var(--badge-bg); border: 1px solid var(--badge-bd);
border-radius: var(--r-pill); padding: 3px 8px 3px 12px;
font-size: 0.71rem; color: var(--badge-fg);
}
.scope-chip strong { font-weight: 600; }
.scope-chip button {
background: none; border: none; color: var(--badge-fg); cursor: pointer;
padding: 0; font-size: 0.85rem; line-height: 1; opacity: 0.6;
}
.scope-chip button:hover { opacity: 1; }

/* === LANDING DASHBOARD === */
.infra-panel {
background: var(--bg-elevated); border: 1px solid var(--border-strong);
border-radius: var(--r-md); overflow: hidden; max-width: 680px; margin-top: 20px;
}
.infra-panel-hdr {
font-size: 0.6rem; font-weight: 700; letter-spacing: 0.13em; text-transform: uppercase;
color: var(--text-3); padding: 11px 20px 10px; border-bottom: 1px solid var(--border);
font-family: var(--font-brand);
}
.infra-section { padding: 8px 0; }
.infra-divider { height: 1px; background: var(--border); }
.infra-row {
display: flex; align-items: center; gap: 12px;
padding: 7px 20px; cursor: pointer; transition: background 0.1s;
}
.infra-row:hover { background: var(--bg-inset); }
.infra-dot  { font-size: 0.55rem; flex-shrink: 0; width: 8px; text-align: center; }
.infra-lbl  { font-size: 0.64rem; font-weight: 700; letter-spacing: 0.09em;
text-transform: uppercase; color: var(--text-3); flex: 0 0 58px; font-family: var(--font-brand); }
.infra-bar-wrap { flex: 1; background: var(--bg-inset); border-radius: 2px; height: 10px; overflow: hidden; }
.infra-bar-fill { height: 100%; border-radius: 2px; transition: width 0.6s ease; }
.infra-nums { font-size: 0.73rem; font-family: var(--font-mono); color: var(--text-2);
flex-shrink: 0; white-space: nowrap; min-width: 180px; text-align: right; }
/* OOS / version sub-rows */
.infra-sub { display: flex; justify-content: space-between; align-items: baseline;
padding: 1px 20px 1px 110px; gap: 16px; }
.infra-sub-os { font-size: 0.67rem; font-family: var(--font-ui); color: var(--text-3);
overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.infra-sub-ct { font-size: 0.67rem; font-family: var(--font-mono); color: var(--text-2);
flex-shrink: 0; }

/* === TABLES === */
table { width: 100%; border-collapse: collapse; font-size: 0.83rem; }
thead tr { background: var(--th-bg); border-bottom: 2px solid var(--border); }
thead th {
text-align: left; padding: 10px 12px; color: var(--th-fg); font-weight: 600;
letter-spacing: 0.05em; font-size: 0.7rem; text-transform: uppercase;
white-space: nowrap; font-family: var(--font-brand);
}
thead th[data-sort] { cursor: pointer; user-select: none; }
thead th[data-sort]:hover { color: var(--accent-h); }
thead th.sorted { color: var(--text-1); }
.sort-ind { margin-left: 3px; font-size: 0.63rem; opacity: 0.4; }
thead th.sorted .sort-ind { opacity: 1; }
tbody tr { border-bottom: 1px solid var(--tr-bd); transition: background 0.1s; }
tbody tr:hover { background: var(--tr-hover); }
tbody td {
padding: 9px 12px; color: var(--text-2); white-space: nowrap;
overflow: hidden; text-overflow: ellipsis; max-width: 220px;
}
tbody td.vm-name { color: var(--text-1); font-weight: 500; }
tbody td.highlight { color: var(--accent); font-weight: 600; }
tbody td.vm-name.highlight { color: var(--text-1); font-weight: 700; }
tbody td.num { text-align: right; font-family: var(--font-mono); color: var(--text-3); }
tbody td.dim { color: var(--text-3); }

/* === BADGES === */
.badge {
display: inline-block; background: var(--badge-bg); border: 1px solid var(--badge-bd);
color: var(--badge-fg); border-radius: var(--r-sm); padding: 1px 7px;
font-size: 0.69rem; font-family: var(--font-mono);
}
.badge-power {
display: inline-block; border-radius: var(--r-sm); padding: 1px 7px;
font-size: 0.67rem; font-weight: 700; letter-spacing: 0.04em;
white-space: nowrap; font-family: var(--font-brand);
}
.badge-power.on        { background: var(--on-bg);   border: 1px solid var(--on-bd);   color: var(--on-fg); }
.badge-power.off       { background: var(--off-bg);  border: 1px solid var(--off-bd);  color: var(--off-fg); }
.badge-power.suspended { background: var(--susp-bg); border: 1px solid var(--susp-bd); color: var(--susp-fg); }
.badge-power.template  { background: var(--tmpl-bg); border: 1px solid var(--tmpl-bd); color: var(--tmpl-fg); }
.badge-tag {
display: inline-block; background: var(--bg-surface); border: 1px solid var(--border);
color: var(--text-2); border-radius: var(--r-sm); padding: 1px 6px;
font-size: 0.66rem; white-space: nowrap; margin: 1px 2px 1px 0;
}
.badge-vlan {
display: inline-block; background: var(--badge-bg); border: 1px solid var(--badge-bd);
color: var(--badge-fg); border-radius: var(--r-sm); padding: 2px 9px;
font-size: 0.72rem; font-family: var(--font-mono); white-space: nowrap;
}
.badge-vlan.matched { background: var(--susp-bg); border-color: var(--susp-bd); color: var(--susp-fg); }
.badge-maint {
background: var(--maint-bg); border: 1px solid var(--maint-bd); color: var(--maint-fg);
border-radius: var(--r-sm); padding: 1px 6px; font-size: 0.66rem; display: inline-block;
}
.empty { text-align: center; padding: 60px 0; color: var(--text-3); font-size: 0.88rem; }

a.vc-link { color: var(--link); text-decoration: none; }
a.vc-link:hover { text-decoration: underline; color: var(--link-h); }
.detail-link { cursor: pointer; color: var(--text-1); border-bottom: 1px dotted var(--border-strong); }
.detail-link:hover { color: var(--accent); border-bottom-color: var(--accent); }

/* === GROUP BLOCKS === */
.group-block { margin-bottom: 14px; border: 1px solid var(--border); border-radius: var(--r-md); overflow: hidden; background: var(--group-bg); }
.group-header {
background: var(--group-hdr); padding: 9px 14px; display: flex;
align-items: baseline; gap: 18px; border-bottom: 1px solid var(--border);
}
.group-header .gh-host { font-size: 0.86rem; font-weight: 600; color: var(--text-1); }
.group-header .gh-cluster { font-size: 0.75rem; color: var(--text-3); }
.group-header .gh-vc { margin-left: auto; font-size: 0.73rem; }
.group-vlans { padding: 10px 14px; display: flex; flex-wrap: wrap; gap: 6px; background: var(--bg); }

/* === COLLAPSIBLE TREE === */
.tree-root { margin-bottom: 20px; }
.tree-root-header {
background: var(--tree-root-bg); border: 1px solid var(--border);
border-radius: var(--r-md) var(--r-md) 0 0;
padding: 10px 16px; display: flex; align-items: center; gap: 14px;
}
.tree-root-header .tr-toggle {
font-size: 0.67rem; color: var(--text-3); width: 20px; height: 20px; flex-shrink: 0;
display: flex; align-items: center; justify-content: center; border-radius: var(--r-sm);
cursor: pointer; transition: transform 0.15s;
}
.tree-root-header .tr-toggle:hover { background: var(--bg-inset); color: var(--text-2); }
.tree-root-header.open .tr-toggle        { transform: rotate(0deg); }
.tree-root-header:not(.open) .tr-toggle  { transform: rotate(-90deg); }
.tree-root-header .tr-name { font-size: 0.9rem; font-weight: 700; color: var(--link); }
.tree-root-header .tr-summary {
font-size: 0.7rem; color: var(--text-2); background: var(--bg-inset);
border: 1px solid var(--border); border-radius: var(--r-sm); padding: 1px 9px;
}
.tree-root-header .tr-vc { margin-left: auto; font-size: 0.73rem; }
.tree-root-header .tr-toggle-all {
font-size: 0.69rem; color: var(--text-3); cursor: pointer; user-select: none;
padding: 2px 8px; border: 1px solid var(--border); border-radius: var(--r-sm);
transition: all 0.15s; margin-left: auto;
}
.tree-root-header .tr-toggle-all:hover { color: var(--text-2); border-color: var(--border-strong); }

.tree-children {
border: 1px solid var(--border); border-top: none;
border-radius: 0 0 var(--r-md) var(--r-md); overflow: hidden; display: none;
}
.tree-children.open { display: block; }
.tree-node-leaves { display: none; }
.tree-node-leaves.open { display: block; }
.tree-node { border-top: 1px solid var(--tr-bd); }
.tree-node:first-child

